class AccountHubRadioCardLarge extends HTMLElement {
  static formAssociated = true;

  /**
   * @type {ElementInternals}
   */
  #internals;

  constructor() {
    super();
    this.#internals = this.attachInternals();
  }

  connectedCallback() {
    if (this.shadowRoot) {
      return;
    }

    this.role = "radio";
    this.#internals.setFormValue(this.getAttribute("value"));
